const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleString('en-GB',{timeZone:'Asia/Dubai'})+' (Dubai)';
const split=value=>String(value||'').split(/[\n,;]+/).map(s=>s.trim()).filter(Boolean);
const link=(url,label)=>{try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);}catch{return esc(label);}};
export function createContactsUI({projects,onChanged,notify}){
 let state={contacts:{},checks:{},registry:null,reoonEnabled:false,apolloEnabled:false,hunterEnabled:false},token='',ready=false,error='',editing=null,checking=false;
 const dialog=document.createElement('dialog');dialog.className='contact-dialog';document.body.appendChild(dialog);
 const api=(route,body)=>request('/wind-projects/api/contacts'+route,body);
 async function request(url,body){const response=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Wind-Token':token}:{},...(body?{body:JSON.stringify(body)}:{})});let payload;try{payload=await response.json();}catch{throw Error('Contact service unavailable. Refresh after starting the updated server.');}if(!response.ok)throw Error(payload.error||'Contact request failed.');return payload;}
 const contacts=p=>state.contacts[p.id]||p.contacts.map((c,i)=>({...c,id:`${p.id}-${i}`,emails:c.email?[c.email.toLowerCase()]:[],phones:Array.isArray(c.phones)?c.phones:[],association:'unconfirmed'}));
 function resultText(result){return `Reoon: ${result.status}\nChecked: ${date(result.checkedAt)}\nMode: Power\nMailbox deliverable: ${result.deliverable?'Yes':'Not confirmed'}\nSafe to send: ${result.raw?.is_safe_to_send===true?'Yes':'Not confirmed'}\nCatch-all: ${result.raw?.is_catch_all===true?'Yes':'No'}\nRole account: ${result.raw?.is_role_account===true?'Yes':'No'}\nScore: ${result.raw?.overall_score??'Not supplied'}\nMailbox verification does not confirm the person’s identity, role or ownership of this email.`;}
 function emailMarkup(email,c){const result=state.checks[email.toLowerCase()];const invalid=/user-reported invalid/i.test(c.original?.status||c.status||'')&&(c.original?.email||email).toLowerCase()===email.toLowerCase();const symbol=result?(result.deliverable?'✓':result.status==='invalid'?'×':result.status==='catch_all'||result.raw?.is_catch_all===true?'≈':'?'):invalid?'×':'○';const style=result?.deliverable?'positive':result?.status==='invalid'||invalid?'negative':'uncertain';const text=result?resultText(result):invalid?'User-reported invalid. No Reoon result recorded.':'Not checked by Reoon.';return `<div class="email-line"><span class="email-value">${esc(email)}</span><button class="copy-email" type="button" data-copy-email="${esc(email)}" title="Copy email address" aria-label="Copy ${esc(email)}">⧉</button><button class="verification-icon ${style}" type="button" data-email-result="${esc(email)}" title="${esc(text)}" aria-label="${esc(email+': '+(result?.status|| (invalid?'user-reported invalid':'not checked'))+'. Show verification details')}">${symbol}</button></div>`;}
 async function copyEmail(email,button){try{await navigator.clipboard.writeText(email);const original=button.textContent;button.textContent='✓';button.classList.add('copied');notify(`Copied ${email}`);setTimeout(()=>{button.textContent=original;button.classList.remove('copied');},1200);}catch{notify('Could not copy the email address.');}}
 function view(p){const entries=contacts(p);return `<div class="contact-toolbar"><div><h2>Project contacts</h2><p class="muted">Reoon runs automatically for new emails. Apollo and Hunter run only when requested.</p></div><button class="primary" data-add-contact="${p.id}" ${!ready?'disabled':''}>+ Add contact</button></div><div class="notice">${error?esc(error):!ready?'Loading the local contact store…':state.reoonEnabled?'Reoon connected · automatic checks use account credits.':'Reoon unavailable — configure the server key. Editing remains available.'} Contact edits and provider history are saved locally. A safe mailbox is not proof of a person-email match.</div><div class="contact-grid">${entries.map(c=>`<article class="card"><div class="avatar">${esc(c.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><h3>${esc(c.name)}</h3><p class="contact-role">${esc(c.title||'Designation not supplied')}</p><p>${esc(c.role||'Decision-making role not confirmed')}</p><div class="contact-emails">${c.emails.map(email=>emailMarkup(email,c)).join('')||'<p class="muted">No email added</p>'}</div><p class="muted contact-association">${c.association==='shared'?'Shared company / project route':c.association==='personal'?'Personal association recorded by user; not independently verified':'Person-email association not independently confirmed'}</p>${c.phones.length?c.phones.map(phone=>`<div class="contact-link">Phone: ${esc(phone)}</div>`).join(''):'<p class="muted">Phone not recorded</p>'}<div class="contact-link">${c.linkedin?link(c.linkedin,'LinkedIn profile ↗'):'LinkedIn not recorded'}</div><div class="contact-link">${c.source?link(c.source,'Contact source ↗'):'Contact source not recorded'}</div>${c.notes?`<p class="contact-notes">${esc(c.notes)}</p>`:''}${c.original?`<details class="contact-original"><summary>Original imported record</summary><p>${esc(c.original.name)} · ${esc(c.original.title)}</p><p>${esc(c.original.email||'No email')} · ${esc(c.original.status)}</p></details>`:''}<div class="contact-actions"><button data-edit-contact="${esc(c.id)}" data-contact-project="${p.id}" ${!ready?'disabled':''}>Edit contact</button><button class="primary" data-check-contact="${esc(c.id)}" data-contact-project="${p.id}" ${!ready||!state.reoonEnabled||!c.emails.length||checking?'disabled':''} title="${c.emails.length?'Recheck saved emails with Reoon Power mode':'Add an email to enable Reoon checking'}">${checking?'Check in progress…':'Reoon check'}</button><button data-enrich="apollo" data-contact-id="${esc(c.id)}" data-contact-project="${p.id}" ${!ready||!state.apolloEnabled||checking?'disabled':''}>Apollo enrich</button><button data-enrich="hunter-find" data-contact-id="${esc(c.id)}" data-contact-project="${p.id}" ${!ready||!state.hunterEnabled||checking?'disabled':''}>Hunter find email</button>${c.emails.map(email=>`<button data-enrich="hunter-verify" data-enrich-email="${esc(email)}" data-contact-id="${esc(c.id)}" data-contact-project="${p.id}" ${!ready||!state.hunterEnabled||checking?'disabled':''}>Hunter verify</button>`).join('')}</div></article>`).join('')||'<div class="card"><p>No contacts yet. Add a contact to get started.</p></div>'}</div>`;}
 function editor(projectId,id){const p=projects.find(p=>p.id===projectId);const c=id?contacts(p).find(c=>c.id===id):{name:'',title:'',role:'',emails:[],phones:[],association:'unconfirmed'};if(!c)return;editing={projectId,id:c.id,version:c.version};dialog.innerHTML=`<form id="contact-editor"><h2>${id?'Edit contact':'Add contact'}</h2><p class="muted">${esc(p.name)} · Saving does not use verification credits.</p><div class="contact-form-grid">${[['name','Full name',true],['title','Designation',false],['role','Role / responsibility',false],['linkedin','LinkedIn profile URL',false],['source','Source URL',false]].map(([field,label,required])=>`<label>${label}<input name="${field}" value="${esc(c[field]||'')}" ${required?'required':''} ${['source','linkedin'].includes(field)?'type="url"':''} maxlength="1000"></label>`).join('')}<label>Email association<select name="association">${[['unconfirmed','Unconfirmed'],['personal','Personal — user supplied'],['shared','Shared company / project']].map(([value,label])=>`<option value="${value}" ${c.association===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Emails — one per line<textarea name="emails" rows="3">${esc(c.emails.join('\n'))}</textarea></label><label>Phones — one per line<textarea name="phones" rows="3">${esc(c.phones.join('\n'))}</textarea></label></div><label>Notes<textarea name="notes" rows="3" maxlength="5000">${esc(c.notes||'')}</textarea></label><p class="form-error" role="alert"></p><div class="contact-actions"><button type="submit" class="primary">Save contact</button><button type="button" data-close-contact>Cancel</button></div></form>`;dialog.showModal();dialog.querySelector('[name="name"]').focus();}
 dialog.addEventListener('click',e=>{if(e.target.closest('[data-close-contact]'))dialog.close();});
 async function autoVerify(projectId,contact,emails){if(!state.reoonEnabled||!emails.length)return 0;checking=true;onChanged();let done=0;try{for(const email of emails){const {result}=await api('/verify',{projectId,contactId:contact.id,email,force:false});state.checks[email.toLowerCase()]=result;done++;}}finally{checking=false;onChanged();}return done;}
 dialog.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id!=='contact-editor')return;const button=form.querySelector('[type="submit"]');button.disabled=true;const input=Object.fromEntries(new FormData(form));input.emails=split(input.emails);input.phones=split(input.phones);const before=editing.id?contacts(projects.find(p=>p.id===editing.projectId)).find(c=>c.id===editing.id):null;const previousEmails=new Set((before?.emails||[]).map(email=>email.toLowerCase()));const changedEmails=input.emails.filter(email=>!previousEmails.has(email.toLowerCase()));Object.assign(input,{id:editing.id,version:editing.version});try{const data=await api('/save',{projectId:editing.projectId,contact:input});const all=state.contacts[editing.projectId]||[];const index=all.findIndex(c=>c.id===data.contact.id);if(index<0)all.push(data.contact);else all[index]=data.contact;state.contacts[editing.projectId]=all;dialog.close();onChanged();if(changedEmails.length&&state.reoonEnabled){try{const done=await autoVerify(editing.projectId,data.contact,changedEmails);notify(`Contact saved. Automatically checked ${done} new or changed email${done===1?'':'s'} with Reoon.`);}catch(error){notify(`Contact saved, but automatic Reoon checking stopped: ${error.message}`);}}else if(changedEmails.length){notify('Contact saved. Automatic Reoon checking is unavailable until the server key is configured.');}else notify('Contact saved locally.');}catch(e){form.querySelector('.form-error').textContent=e.message;}finally{button.disabled=false;}});
 function suggestedDomain(p,c){const saved=c.emails?.map(e=>e.split('@')[1]).find(Boolean);if(saved)return saved;const context=`${p.developer||''} ${c.title||''} ${c.role||''}`.toLowerCase();if(context.includes('agl'))return'agl.com.au';if(context.includes('wind prospect'))return'windprospect.com.au';if(context.includes('aes'))return'aes.com';return'';}
 function resultEmail(result){return String(result?.data?.email||result?.person?.email||result?.email||'').trim().toLowerCase();}
 async function saveProviderEmail(projectId,contactId,email){const p=projects.find(p=>p.id===projectId),c=contacts(p).find(c=>c.id===contactId);if(!c||!email)return;const emails=[...new Set([...(c.emails||[]),email])];const payload={...c,emails,id:c.id,version:c.version};const data=await api('/save',{projectId,contact:payload});const all=state.contacts[projectId]||[];const index=all.findIndex(x=>x.id===data.contact.id);if(index<0)all.push(data.contact);else all[index]=data.contact;state.contacts[projectId]=all;dialog.close();onChanged();if(state.reoonEnabled){try{const {result}=await api('/verify',{projectId,contactId:data.contact.id,email,force:false});state.checks[email]=result;onChanged();notify(`Email saved to ${c.name} and checked automatically with Reoon.`);}catch(error){notify(`Email saved to ${c.name}; automatic Reoon check failed: ${error.message}`);}}else notify(`Email saved to ${c.name}.`);}
 async function enrich(kind,projectId,contactId,email){const p=projects.find(p=>p.id===projectId),c=contacts(p).find(c=>c.id===contactId);if(!c)return;let domain='';if(kind==='apollo'&&!c.emails.length||kind==='hunter-find'){const suggested=suggestedDomain(p,c);domain=suggested||prompt(`Enter the company domain for ${c.name} (for example agl.com.au):`,'');if(!domain)return;}checking=true;onChanged();try{const body=kind==='apollo'?{provider:'apollo',action:'enrich',projectId,contactId,domain}:{provider:'hunter',action:kind==='hunter-find'?'find-email':'verify-email',projectId,contactId,...(kind==='hunter-find'?{domain}:{email})};const data=await api('/enrich',body);const result=data.result;const found=resultEmail(result);dialog.innerHTML=`<h2>${kind==='apollo'?'Apollo enrichment':'Hunter result'}</h2><p class="muted">${esc(c.name)} · Result saved to provider history. Manual contact fields were not changed.</p><pre class="verification-detail"></pre><div class="contact-actions">${found?`<button class="primary" data-save-provider-email="${esc(found)}" data-save-provider-project="${esc(projectId)}" data-save-provider-contact="${esc(contactId)}">Save ${esc(found)} to contact</button>`:''}<button data-close-contact>Close</button></div>`;dialog.querySelector('pre').textContent=JSON.stringify(result,null,2);dialog.showModal();notify(`${kind==='apollo'?'Apollo':'Hunter'} result saved. Review it before editing the contact.`);}catch(error){notify(error.message);}finally{checking=false;onChanged();}}
 document.addEventListener('click',async e=>{
  const remove=e.target.closest('[data-delete-contact]');if(!remove||checking)return;
  const projectId=remove.dataset.contactProject;const p=projects.find(p=>p.id===projectId);const c=p&&contacts(p).find(c=>c.id===remove.dataset.deleteContact);
  if(!c||!ready)return;
  if(!confirm(`Delete contact ${c.name}? The contact will be removed from the active list, while its deletion history is retained.`))return;
  checking=true;onChanged();
  try{await api('/delete',{projectId,contactId:c.id,version:c.version});await load();notify(`Deleted contact ${c.name}.`);}catch(error){notify(`Contact was not deleted: ${error.message}`);}finally{checking=false;onChanged();}
 });
 document.addEventListener('click',async e=>{
  const add=e.target.closest('[data-add-contact]');if(add)return editor(add.dataset.addContact);
  const edit=e.target.closest('[data-edit-contact]');if(edit)return editor(edit.dataset.contactProject,edit.dataset.editContact);
  const copy=e.target.closest('[data-copy-email]');if(copy){return copyEmail(copy.dataset.copyEmail,copy);}
  const detail=e.target.closest('[data-email-result]');if(detail){const result=state.checks[detail.dataset.emailResult.toLowerCase()];dialog.innerHTML=`<h2>Email verification</h2><p>${esc(detail.dataset.emailResult)}</p><pre class="verification-detail"></pre><button data-close-contact>Close</button>`;dialog.querySelector('pre').textContent=result?resultText(result):detail.title;dialog.showModal();return;}
  const saveProvider=e.target.closest('[data-save-provider-email]');if(saveProvider){return saveProviderEmail(saveProvider.dataset.saveProviderProject,saveProvider.dataset.saveProviderContact,saveProvider.dataset.saveProviderEmail);}
  const enrichButton=e.target.closest('[data-enrich]');if(enrichButton){return enrich(enrichButton.dataset.enrich==='hunter-find'?'hunter-find':enrichButton.dataset.enrich==='hunter-verify'?'hunter-verify':'apollo',enrichButton.dataset.contactProject,enrichButton.dataset.contactId,enrichButton.dataset.enrichEmail||'');}
  const check=e.target.closest('[data-check-contact]');if(!check||checking)return;
  const projectId=check.dataset.contactProject;const c=contacts(projects.find(p=>p.id===projectId)).find(c=>c.id===check.dataset.checkContact);
  if(!c?.emails.length)return;
  checking=true;onChanged();let done=0;
  try{for(const email of c.emails){const {result}=await api('/verify',{projectId,contactId:c.id,email,force:true});state.checks[email.toLowerCase()]=result;done++;}notify(`Reoon check complete: ${done} email(s). Hover over the icons for results.`);}catch(e){notify(`${done} checked. ${e.message}`);}finally{checking=false;onChanged();}
 });
 async function verifyUncachedEmails(){
  if(!state.reoonEnabled)return;
  const queue=[];
  for(const [projectId,entries] of Object.entries(state.contacts))for(const contact of entries)for(const email of contact.emails||[]){
   const invalid=/user-reported invalid/i.test(contact.original?.status||contact.status||'')&&(contact.original?.email||email).toLowerCase()===email.toLowerCase();
   if(!state.checks[email.toLowerCase()]&&!invalid)queue.push({projectId,contact,email});
  }
  for(const item of queue){
   try{const {result}=await api('/verify',{projectId:item.projectId,contactId:item.contact.id,email:item.email,force:false});state.checks[item.email.toLowerCase()]=result;onChanged();}
   catch(error){if(/unavailable|server key|credits|respond|HTTP/i.test(error.message))break;}
  }
 }
 return {request,isReady:()=>ready,view:p=>view(p).replace('Hover over a status icon for the Reoon result, or click it for full details.','New or changed emails are checked automatically. Use Reoon check for an on-demand recheck.').replace('on-demand checks use account credits.','automatic checks use account credits.').replace('Check saved emails with Reoon Power mode','Recheck saved emails with Reoon Power mode'),contacts,snapshot:()=>state,verifiedCount:(p)=>{const emails=p?contacts(p).flatMap(c=>c.emails):Object.values(state.contacts).flat().flatMap(c=>c.emails);return [...new Set(emails)].filter(e=>state.checks[e]?.deliverable).length;},async load(){try{const data=await api('');token=data.token;delete data.token;const localKey=projects.map(project=>project.id).join('|');const remoteKey=data.registry?.key||Object.keys(data.contacts||{}).join('|');if(localKey!==remoteKey||projects.length!==Object.keys(data.contacts||{}).length){state=data;ready=false;error='Project registry mismatch — restart the Wind Projects server before editing contacts or running verification.';onChanged();return;}state=data;ready=true;error='';}catch(e){error=e.message;}onChanged();if(ready)void verifyUncachedEmails();}};
}
